create or replace function public.add_relationship_occupant(p_relationship_id uuid,p_person_id uuid,p_starts_on date default current_date,p_ends_on date default null) returns public.rental_participants language plpgsql security definer set search_path='' as $$ declare r public.rental_relationships; x public.rental_participants; v_status public.participation_status; begin select * into r from public.rental_relationships where id=p_relationship_id; if not found then raise exception 'RENTAL_RELATIONSHIP_NOT_FOUND'; end if; if public.can_manage_administration(r.administration_id) is not true then raise exception 'MANAGEMENT_ACCESS_REQUIRED'; end if; if r.status not in('DRAFT','ACTIVE','ENDING') then raise exception 'RENTAL_NOT_OPEN_FOR_OCCUPANTS'; end if; if p_ends_on is not null and p_ends_on<p_starts_on then raise exception 'INVALID_OCCUPANT_DATES'; end if; v_status:=case when p_ends_on is not null and p_ends_on<current_date then 'ENDED'::public.participation_status else 'ACTIVE'::public.participation_status end; insert into public.rental_participants(rental_relationship_id,person_id,participation_type,status,starts_on,ends_on) values(r.id,p_person_id,'OCCUPANT',v_status,p_starts_on,p_ends_on) returning * into x; return x; end $$;